  },
  "repositories": [
    {
      "type": "vcs",
      "url": "https://github.com/k-kinzal/php-ai-toolkit.git",
      "no-api": true
    }
  ],
  "require": {
    "php": "^8.0"
  },
  "autoload": {
    "classmap": [
      "src/php"
    ]
  },
  "require-dev": {
    "brianium/paratest": "^6.11 || ^7",
